let projectDocs={},buildGuides={},guideVariantLabel="";
function guideFor(g){
 const manual=PROJECT_GUIDES[String(g.repo||'').toLowerCase()];if(manual)return {...manual,reviewed:true};
 const extracted=buildGuides[String(g.repo||'').toLowerCase()];if(extracted)return extracted;
 if(g.browser){if(!safeURL(g.links?.play))return {requirements:[g.limitations||'Acompanhe as fontes oficiais para verificar a disponibilidade.'],steps:[],note:'Este registro não tem um acesso jogável confirmado. Consulte as notícias e as fontes do projeto.'};
 return {requirements:[g.status||'Confira a disponibilidade na página oficial.',g.limitations||'Confira os requisitos informados pelo projeto.'],steps:[['Abra a página do jogo','Use o botão Jogar para acessar o endereço indicado pelo projeto.'],['Confira os requisitos','Leia as orientações da página antes de carregar o jogo. Se forem solicitados arquivos originais, use os da sua própria cópia.'],['Configure e experimente','Siga os comandos e as opções apresentados pelo projeto para configurar os controles e iniciar.']],note:'A disponibilidade do endereço não confirma que o jogo possa ser concluído. O desempenho depende do projeto e do dispositivo.'};}
 return {pending:true,source:safeURL(g.url)+'#readme',requirements:['Ainda não foram confirmados os passos de instalação deste projeto.'],steps:[],note:'Este projeto ainda não tem um tutorial em português pronto. Os links oficiais permanecem disponíveis ao lado para consulta, sem um passo a passo genérico apresentado como tutorial.'};
}
function externalLink(label,url,cls=''){return safeURL(url)?'<a class="'+cls+'" href="'+esc(safeURL(url))+'" target="_blank" rel="noopener noreferrer">'+esc(label)+' ↗</a>':''}
function projectAuthor(g){
 const match=/^([a-z0-9][a-z0-9-]{0,38})\/[a-z0-9_.-]+$/i.exec(String(g.repo||''));
 if(match)return '<span>Autor:</span> <a href="https://github.com/'+encodeURIComponent(match[1])+'" target="_blank" rel="noopener noreferrer">'+esc(match[1])+'</a>';
 return '<span>Autor:</span> '+esc(g.publisher||'Não informado');
}
function renderProject(g){
 const guide=guideFor(g),variants=guide.variants||[],steps=(variants.find(v=>v.label===guideVariantLabel)||variants[0]||guide).steps,displayTitle=guide.title||g.title,docs=projectDocs[String(g.repo||'').toLowerCase()],links=docs?.links||[];
 document.title=displayTitle+' — jogosrecompilados.com.br';
 $('#projectContent').innerHTML='<section class="project-hero"><div class="project-overview"><span class="eyebrow">'+esc(labels[g.type])+'</span><h1>'+esc(displayTitle)+'</h1><p class="project-by">'+projectAuthor(g)+'</p><div class="project-facts"><span>'+esc(g.platform||'Plataforma não informada')+'</span><span>☆ '+Number(g.stars||0).toLocaleString('pt-BR')+' estrelas</span><span>'+esc(g.browser?g.status:g.release?'Versão '+g.release:'Sem release identificada')+'</span></div><p class="project-summary">'+esc(g.browser?g.description:guide.reviewed?'Conheça o projeto e siga o passo a passo em português para começar.':guide.extracted?'Veja os requisitos e os comandos de compilação publicados pelo autor, com as etapas explicadas em português.':'Conheça o estado do projeto e suas fontes oficiais.')+'</p><div class="project-actions">'+externalLink(g.browser?'Fonte do projeto':'GitHub do projeto',g.url,'primary')+'<a class="secondary" href="#guia">'+(guide.pending?'Tutorial em preparação':guide.extracted?'Ver compilação ↓':'Ver tutorial ↓')+'</a><button id="projectFavorite" class="secondary" aria-pressed="'+favorites.has(g.id)+'">'+(favorites.has(g.id)?'♥ Favoritado':'♡ Favoritar')+'</button></div></div><div class="project-visual"><img id="projectImage" src="'+esc(picture(g))+'" alt="'+esc(g.title)+'"><span>'+esc(g.platform||'Comunidade')+'</span></div></section><div class="project-layout"><section class="project-guide" id="guia"><div class="eyebrow">DO PROJETO AO PRIMEIRO PLAY</div><h2>'+(guide.pending?'Tutorial em preparação':g.browser?'Como acessar':guide.extracted?'Como compilar o projeto':guide.buildOnly?'Como compilar e jogar':'Como começar a jogar')+'</h2><p class="guide-intro">'+(guide.reviewed?(guide.buildOnly?'Guia baseado no README e no arquivo de compilação, conferido em ':'Resumo em português do README oficial, conferido em ')+date(guide.checked)+'.':g.browser?'Orientações com base nas fontes e nas limitações do catálogo.':guide.extracted?'Escolha a opção disponível para seu sistema e use a sequência abaixo. Os comandos são os publicados pelo autor.':'Ainda não há um procedimento de instalação confirmado para publicar aqui.')+'</p><div class="requirements"><h3>'+(guide.pending?'Situação do guia':'Antes de começar')+'</h3><ul>'+guide.requirements.map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul></div>'+(variants.length>1?'<label class="guide-variant-label">Sistema / opção de compilação<select id="guideVariant">'+variants.map(v=>'<option '+(steps===v.steps?'selected':'')+' value="'+esc(v.label)+'">'+esc(v.label)+'</option>').join('')+'</select></label>':'')+'<ol class="guide-steps">'+steps.map(([title,text,commands])=>'<li><h3>'+esc(title)+'</h3><p>'+esc(text)+'</p>'+(commands?'<pre class="guide-command"><code>'+esc(commands)+'</code></pre>':'')+'</li>').join('')+'</ol>'+(guide.note?'<p class="guide-note">'+esc(guide.note)+'</p>':'')+'</section><aside class="project-sidebar"><section><h2>Links do projeto</h2><div class="project-resource-list">'+cardLinks(g)+(guide.source?externalLink('README original',guide.source):'')+(guide.links||[]).map(([label,url])=>externalLink(label,url)).join('')+'</div></section>'+(links.length?'<section><h2>Documentação oficial</h2><div class="project-resource-list">'+links.map(link=>externalLink(link.label,link.url)).join('')+'</div><p class="source-date">README consultado em '+date(docs.checked)+'.</p></section>':'')+'<section><h2>Sobre esta versão</h2><p>Última atividade: '+date(g.last_commit)+'.</p>'+(g.archived?'<p>O repositório está arquivado.</p>':'')+'<p>Confira os requisitos e as notas do autor antes de instalar ou atualizar.</p></section></aside></div>';
 bindImageFallback($('#projectImage'),g);
 if(variants.length>1)$('#guideVariant').onchange=e=>{guideVariantLabel=e.target.value;renderProject(g)};
 $('#projectFavorite').onclick=()=>{favorites.has(g.id)?favorites.delete(g.id):favorites.add(g.id);try{localStorage.setItem('atlas-favorites',JSON.stringify([...favorites]))}catch{}const b=$('#projectFavorite');b.setAttribute('aria-pressed',String(favorites.has(g.id)));b.textContent=favorites.has(g.id)?'♥ Favoritado':'♡ Favoritar'};
}
async function initProject(){
 const id=new URLSearchParams(location.search).get('id');if(!id){$('#projectContent').innerHTML='<h1>Escolha um projeto</h1><p>Volte ao catálogo para abrir o jogo que você quer conhecer.</p>';return}
 let best=null,found=false;
 try{const cached=JSON.parse(localStorage.getItem('atlas-catalog')||'null');if(cached){normalized(cached);best=cached}}catch{}
 try{const bundled=await getJSON('catalog.json');normalized(bundled);if(!best||Date.parse(bundled.generated_at)>Date.parse(best.generated_at))best=bundled}catch{}
 const show=data=>{const g=normalized(data).find(g=>g.id===id);if(g){found=true;renderProject(g)}return g};
 if(best)show(best);
 getJSON('build-guides.json').then(data=>{buildGuides=data.projects||{};if(best)show(best)}).catch(()=>{});
 getJSON('project-docs.json').then(data=>{projectDocs=data.projects||{};if(best)show(best)}).catch(()=>{});
 try{const live=await getJSON(SOURCE+'data/games.json');normalized(live);best=live;show(live);try{localStorage.setItem('atlas-catalog',JSON.stringify(live))}catch{}}catch{}
 if(!found)$('#projectContent').innerHTML='<h1>Projeto não encontrado</h1><p>Ele pode ter mudado de endereço ou a fonte está indisponível. Procure o nome no catálogo.</p>';
}
initProject();
